/**
 * Calculate the discount amount for a line item (including bulk discount for qty >= 10).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const total = lineTotal(line);
  const regularDiscount = total * ((line.discountPercent ?? 0) / 100);
  const afterRegular = Math.max(0, total - regularDiscount);
  const bulkDiscount = line.qty >= 10 ? afterRegular * 0.025 : 0;
  return Math.max(0, regularDiscount + bulkDiscount);
}

