  const vatAt10 = lineVat({ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 10 });
  assert.equal(vatAt9, 900);
  assert.equal(vatAt10, 975);
});

test('invoiceTotals with mixed qty (some with bulk, some without)', () => {
  const invoice = {
    lines: [
      { qty: 15, unitPrice: 1000, vatRate: 0 },
      { qty: 5, unitPrice: 1000, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.subtotal, 20000);
  assert.equal(result.discount, 375);
  assert.equal(result.vat, 0);
  assert.equal(result.total, 19625);
});

test('invoiceTotals: bulk discount with tier discount', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 5 }],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.subtotal, 100000);
  assert.equal(result.discount, 7375);
});

