10	/**
11	 * Validate a discount percent value.
12	 * @param {any} discountPercent
13	 * @returns {boolean}
14	 */
15	function isValidDiscount(discountPercent) {
16	  if (discountPercent === undefined || discountPercent === null) {
17	    return true;
18	  }
19	  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
20	}
21	
22	/**
23	 * Calculate the due date for an invoice based on terms.
24	 * @param {string} issueDate - Date in YYYY-MM-DD format
25	 * @param {string} terms - Payment terms: NET14, NET30, or EOM
26	 * @returns {string|null} Due date in YYYY-MM-DD format, or null if terms are invalid
27	 */
28	function calculateDueDate(issueDate, terms) {
29	  if (terms === 'NET14') {
30	    return addDays(issueDate, 14);
31	  }
32	  if (terms === 'NET30') {
33	    return addDays(issueDate, 30);
34	  }
35	  if (terms === 'EOM') {
36	    const [year, month] = issueDate.split('-');
37	    const nextMonth = parseInt(month) + 1;
38	    if (nextMonth > 12) {
39	      return `${parseInt(year) + 1}-01-01`;
40	    }
41	    return `${year}-${String(nextMonth).padStart(2, '0')}-01`;
42	  }
43	  return null;
44	}
45	
46	/**
47	 * Get the last day of the month for an EOM due date.
48	 * @param {string} issueDate - Date in YYYY-MM-DD format
49	 * @returns {string} Last day of the month in YYYY-MM-DD format
50	 */
51	function getEndOfMonth(issueDate) {
52	  const [year, month] = issueDate.split('-');
53	  const nextMonth = parseInt(month) + 1;
54	  let nextMonthStr, nextYearStr;
55	  if (nextMonth > 12) {
56	    nextYearStr = String(parseInt(year) + 1);
57	    nextMonthStr = '01';
58	  } else {
59	    nextYearStr = year;
60	    nextMonthStr = String(nextMonth).padStart(2, '0');
61	  }
62	  const firstDayNextMonth = `${nextYearStr}-${nextMonthStr}-01`;
63	  const d = new Date(firstDayNextMonth + 'T00:00:00Z');
64	  d.setUTCDate(d.getUTCDate() - 1);
65	  return d.toISOString().split('T')[0];
66	}
