68	/**
69	 * Create a new invoice.
70	 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }}
71	 * @returns {import('./result.js').Result}
72	 */
73	export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
74	  // Normalize customer ID
75	  const normalizedCustomerId = normalizeId(customerId);
76	
77	  // Validate date
78	  if (!isValidDate(issueDate)) {
79	    return fail('DATE_INVALID');
80	  }
81	
82	  // Validate terms
83	  if (terms !== 'NET14' && terms !== 'NET30' && terms !== 'EOM') {
84	    return fail('TERMS_INVALID');
85	  }
86	
87	  // Validate lines array is not empty
88	  if (!lines || lines.length === 0) {
89	    return fail('NO_LINES');
90	  }
91	
92	  // Validate customer exists
93	  const customerResult = getCustomer(normalizedCustomerId);
94	  if (!customerResult.ok) {
95	    return customerResult;
96	  }
97	
98	  const customer = customerResult.value;
99	
100	  // Process lines
101	  const processedLines = [];
102	  for (const line of lines) {
103	    // Validate qty
104	    if (!Number.isInteger(line.qty) || line.qty <= 0) {
105	      return fail('QTY_INVALID');
106	    }
107	
108	    // Validate discount
109	    if (!isValidDiscount(line.discountPercent)) {
110	      return fail('DISCOUNT_INVALID');
111	    }
112	
113	    // Validate SKU exists
114	    const productResult = getProduct(line.sku);
115	    if (!productResult.ok) {
116	      return productResult;
117	    }
118	
119	    const product = productResult.value;
120	    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];
121	    processedLines.push({
122	      sku: line.sku,
123	      name: product.name,
124	      qty: line.qty,
125	      unitPrice: product.unitPrice,
126	      vatRate: product.vatRate,
127	      discountPercent,
128	    });
129	  }
130	
131	  // Calculate due date based on terms
132	  const dueDate = terms === 'EOM' ? getEndOfMonth(issueDate) : calculateDueDate(issueDate, terms);
133	
134	  return ok({
135	    customerId: normalizedCustomerId,
136	    issueDate,
137	    status: 'draft',
138	    lines: processedLines,
139	    terms,
140	    dueDate,
141	  });
142	}
