1	/**
2	 * Calculate the total for a line item (before discount).
3	 * @param {{ qty: number, unitPrice: number }} line
4	 * @returns {number}
5	 */
6	export function lineTotal(line) {
7	  return Math.max(0, line.qty * line.unitPrice);
8	}
9	
10	/**
11	 * Calculate the discount amount for a line item (including bulk discount for qty >= 10).
12	 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
13	 * @returns {number}
14	 */
15	export function lineDiscount(line) {
16	  const total = lineTotal(line);
17	  const regularDiscount = total * ((line.discountPercent ?? 0) / 100);
18	  const afterRegular = Math.max(0, total - regularDiscount);
19	  const bulkDiscount = line.qty >= 10 ? afterRegular * 0.025 : 0;
20	  return Math.max(0, regularDiscount + bulkDiscount);
21	}
22	
23	/**
24	 * Calculate the VAT amount for a line item (VAT is calculated on amount after regular and bulk discounts).
25	 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }} line
26	 * @returns {number}
27	 */
28	export function lineVat(line) {
29	  const total = lineTotal(line);
30	  const regularDiscount = total * ((line.discountPercent ?? 0) / 100);
31	  const afterRegular = Math.max(0, total - regularDiscount);
32	  const bulkDiscount = line.qty >= 10 ? afterRegular * 0.025 : 0;
33	  const amountAfterAllDiscounts = Math.max(0, afterRegular - bulkDiscount);
34	  const vat = amountAfterAllDiscounts * ((line.vatRate ?? 0) / 100);
35	  return Math.round(vat);
36	}
37	
38	/**
39	 * Calculate totals for an invoice.
40	 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }>, voucher?: { code: string, amount: number } }} invoice
41	 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
42	 */
43	export function invoiceTotals(invoice) {
44	  const subtotal = Math.max(0, invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0));
45	  const discount = Math.round(Math.max(0, invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0)));
46	  const vat = Math.max(0, invoice.lines.reduce((sum, line) => sum + lineVat(line), 0));
47	  const voucher = invoice.voucher ? invoice.voucher.amount : 0;
48	  const total = Math.max(0, subtotal - discount + vat - voucher);
49	  return {
50	    subtotal,
51	    discount,
52	    vat,
53	    voucher,
54	    total,
55	  };
56	}
