1	import { getCustomer } from './customers.js';
2	import { invoiceTotals } from './invoices.js';
3	import { balanceDue } from './payments.js';
4	
5	/**
6	 * Format cents as plain euros with 2 decimals and a dot: 1234.50
7	 * @param {number} cents
8	 * @returns {string}
9	 */
10	function formatEuros(cents) {
11	  const euros = cents / 100;
12	  return euros.toFixed(2);
13	}
14	
15	/**
16	 * Escape a CSV field: quote if it contains comma, double quote, or newline.
17	 * @param {string} field
18	 * @returns {string}
19	 */
20	function escapeCsvField(field) {
21	  const str = String(field);
22	  if (str.includes(',') || str.includes('"') || str.includes('\n')) {
23	    return '"' + str.replace(/"/g, '""') + '"';
24	  }
25	  return str;
26	}
27	
28	/**
29	 * Join fields into a CSV line.
30	 * @param {string[]} fields
31	 * @returns {string}
32	 */
33	function escapeCsvLine(fields) {
34	  return fields.map(escapeCsvField).join(',');
35	}
36	
37	/**
38	 * Export invoices to CSV format.
39	 * @param {any[]} invoices
40	 * @returns {string}
41	 */
42	export function exportCsv(invoices) {
43	  const lines = [];
44	  lines.push('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
45	
46	  invoices.forEach(inv => {
47	    const customer = getCustomer(inv.customerId);
48	    const customerName = customer.ok ? customer.value.name : '';
49	    const totals = invoiceTotals(inv);
50	    const due = balanceDue(inv);
51	
52	    const fields = [
53	      inv.number || '',
54	      customerName,
55	      inv.issueDate,
56	      inv.dueDate,
57	      inv.status,
58	      formatEuros(totals.subtotal),
59	      formatEuros(totals.discount),
60	      formatEuros(totals.vat),
61	      formatEuros(totals.total),
62	      formatEuros(due),
63	    ];
64	
65	    lines.push(escapeCsvLine(fields));
66	  });
67	
68	  return lines.join('\n') + '\n';
69	}
