1	import { ok, fail } from './result.js';
2	import { invoiceTotals } from './invoices.js';
3	
4	/**
5	 * Calculate the amount still owed on an invoice.
6	 * @param {any} invoice
7	 * @returns {number}
8	 */
9	export function balanceDue(invoice) {
10	  const total = invoiceTotals(invoice).total;
11	  if (!invoice.payments || invoice.payments.length === 0) {
12	    return total;
13	  }
14	  const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
15	  return total - totalPaid;
16	}
17	
18	/**
19	 * Record a payment on an invoice.
20	 * @param {any} invoice
21	 * @param {{ amount: number, date: string }} payment
22	 * @returns {import('./result.js').Result}
23	 */
24	export function recordPayment(invoice, { amount, date }) {
25	  // Validate invoice is issued or partially paid
26	  if (invoice.status !== 'issued' && invoice.status !== 'partially_paid') {
27	    return fail('NOT_ISSUED');
28	  }
29	
30	  // Validate amount
31	  if (!Number.isInteger(amount) || amount <= 0) {
32	    return fail('AMOUNT_INVALID');
33	  }
34	
35	  // Calculate balance due
36	  const balance = balanceDue(invoice);
37	
38	  // Check for overpayment
39	  if (amount > balance) {
40	    return fail('OVERPAYMENT');
41	  }
42	
43	  // Create or copy payments array
44	  const payments = invoice.payments ? [...invoice.payments] : [];
45	  payments.push({ amount, date });
46	
47	  // Calculate new status
48	  const newBalance = balance - amount;
49	  const newStatus = newBalance === 0 ? 'paid' : 'partially_paid';
50	
51	  return ok({
52	    ...invoice,
53	    payments,
54	    status: newStatus,
55	  });
56	}
